import functools


def 记一笔(fn):
    @functools.wraps(fn)
    def 包装(*args, **kwargs):
        print("喂进来的是 " + str(args))
        print("要施展的是 " + fn.__name__)
        return fn(*args, **kwargs)

    return 包装


@记一笔
def 加鱼干(a, b):
    return a + b


a = int(input())
b = int(input())
print(加鱼干(a, b))
